const BASE = process.env.REACT_APP_API_URL || "http://localhost:3001";
async function post(endpoint, body) {
  const res = await fetch(`${BASE}${endpoint}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!res.ok) { const e = await res.json().catch(()=>({error:res.statusText})); throw new Error(e.error||"API error"); }
  return res.json();
}
async function get(endpoint) {
  const res = await fetch(`${BASE}${endpoint}`, {
    method: "GET",
    headers: { "Content-Type": "application/json" },
  });
  if (!res.ok) { const e = await res.json().catch(()=>({error:res.statusText})); throw new Error(e.error||"API error"); }
  return res.json();
}
export const api = {
  chat: (question, userContext, conversationHistory, lang) =>
    post("/api/chat", { question, userContext, conversationHistory, lang }),
  exportPDF: (conversation, userContext) =>
    post("/api/export-pdf", { conversation, userContext }),
  getAnalytics: () =>
    get("/api/analytics"),
};
